import{_ as t,o as a,c as s,ah as r}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Administrateur","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/index.md","filePath":"src/guide/admin/index.md"}'),i={name:"guide/admin/index.md"};function n(l,e,d,o,u,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="administrateur" tabindex="-1">Administrateur <a class="header-anchor" href="#administrateur" aria-label="Permalink to &quot;Administrateur&quot;">​</a></h1><p>En tant qu&#39;administrateur, vous avez accès à l&#39;ensemble de la structure de votre établissement : configuration de base, personnel, élèves, tarification, emplois du temps et bulletins. C&#39;est le rôle le plus complet d&#39;ERA — la plupart des autres rôles (enseignant, secrétariat, caisse...) travaillent dans un périmètre que vous avez préalablement mis en place.</p><h2 id="ou-trouver-les-outils-d-administration" tabindex="-1">Où trouver les outils d&#39;administration <a class="header-anchor" href="#ou-trouver-les-outils-d-administration" aria-label="Permalink to &quot;Où trouver les outils d&#39;administration&quot;">​</a></h2><p>La colonne des espaces, à gauche, est organisée par domaine ; chaque espace présente ses pages en onglets en haut de l&#39;écran (voir <a href="/era-guide/guide/prise-en-main.html#se-reperer-dans-l-application">Se repérer dans l&#39;application</a>). Les écrans que vous utilisez au quotidien sont en haut :</p><ul><li><strong>Élèves et admissions</strong> : les élèves, les nouveaux dossiers, les dossiers à traiter et la mobilité inter-site.</li><li><strong>Enseignement</strong> et <strong>Vie scolaire</strong> : les emplois du temps, les présences, la discipline et les présences périscolaires.</li><li><strong>Services aux élèves</strong> : la cantine, le transport, l&#39;internat et l&#39;infirmerie.</li><li><strong>Finances</strong> : la facturation et les dépenses.</li><li><strong>Personnel</strong> : les employés, les demandes de congé et les mutations de personnel.</li></ul><p>Les écrans de mise en place, que l&#39;on ouvre plus rarement, sont dans deux espaces à part, en bas de la colonne :</p><ul><li><strong>Paramétrage scolaire</strong> : années et périodes scolaires, sites, départements, niveaux, classes, matières, matières par département, affectations enseignants, types d&#39;évaluation, compétences, grilles de frais, circuits de transport, activités et séances périscolaires.</li><li><strong>Administration</strong> : utilisateurs, journal d&#39;activité, <a href="/era-guide/guide/admin/page-accueil.html">Page d&#39;accueil</a> et <a href="/era-guide/guide/admin/parametres-application.html">Paramètres de l&#39;application</a>.</li></ul><p>L&#39;espace <strong>Paramétrage scolaire</strong> compte beaucoup de pages : faites défiler ses onglets horizontalement pour les voir toutes.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page du guide</th><th>Ce qu&#39;elle couvre</th></tr></thead><tbody><tr><td><a href="/era-guide/guide/admin/tableau-de-bord.html">Tableau de bord</a></td><td>Les indicateurs de pilotage de l&#39;établissement (effectifs, résultats, absentéisme, trésorerie) et leur export</td></tr><tr><td><a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a></td><td>Années scolaires, périodes, sites, départements, niveaux, classes, matières, référentiels de compétences et types d&#39;évaluation — la configuration de base à faire en début d&#39;année, et la préparation de l&#39;année suivante</td></tr><tr><td><a href="/era-guide/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a></td><td>Créer des comptes et leur assigner un rôle, gérer les fiches et contrats du personnel, affecter les enseignants, traiter les mutations de site</td></tr><tr><td><a href="/era-guide/guide/admin/eleves-tuteurs.html">Élèves et tuteurs</a></td><td>Dossiers élèves, comptes élève et tuteur, matières de spécialité</td></tr><tr><td><a href="/era-guide/guide/admin/frais-tarification.html">Frais et tarification</a></td><td>Grilles de frais par site/département/année et remises accordées aux élèves</td></tr><tr><td><a href="/era-guide/guide/admin/emplois-du-temps.html">Emplois du temps</a></td><td>Construire l&#39;emploi du temps hebdomadaire de chaque classe</td></tr><tr><td><a href="/era-guide/guide/admin/bulletins.html">Bulletins</a></td><td>Publier et télécharger les bulletins d&#39;une classe pour une période donnée</td></tr><tr><td><a href="/era-guide/guide/admin/activites-extrascolaires.html">Activités extrascolaires</a></td><td>Créer le catalogue d&#39;activités périscolaires et planifier leurs séances</td></tr><tr><td><a href="/era-guide/guide/admin/page-accueil.html">Page d&#39;accueil</a></td><td>Configurer la page publique de l&#39;établissement : accroche, présentation, départements et foire aux questions</td></tr><tr><td><a href="/era-guide/guide/admin/parametres-application.html">Paramètres de l&#39;application</a></td><td>Identité, couleurs, logos, personnalisation des reçus, et les deux réglages qui changent le comportement de l&#39;app</td></tr><tr><td><a href="/era-guide/guide/admin/demo-et-journal.html">Démo complète et journal d&#39;activité</a></td><td>Activer la démo complète (établissements Era Admission en version gratuite) et consulter l&#39;historique des actions</td></tr></tbody></table><p>Les paramètres qui concernent votre propre compte (profil, sécurité, notifications, langue) sont communs à tous les rôles — voir <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a>.</p>',11)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
